import sites from '../../data/spawn-sites.json' with {type:'json'};
import {BOUNDS,MAP} from './map.ts';
import {TERRAIN_REVISION} from './terrain-navigation.ts';
import {KINDS,LEADERS,MAP_ID} from './content.ts';
import type {PlayerSetup} from './types.ts';
// Generated by scripts/build-spawn-sites.mjs from legal bidirectional land links.
// A single-region pool includes all eligible regions with a real land exit.
// This is the available map resource, not a configured player/AI seat ceiling.
if(sites.mapId!==MAP_ID||sites.terrainRevision!==TERRAIN_REVISION)throw new Error('incompatibleMap');
const availableRegions=new Set<number>();
for(const id of sites.regions){
 if(!MAP[id]?.playable||!MAP[id].locked||availableRegions.has(id))throw new Error('noSpawnRegions');
 availableRegions.add(id);
}
export function getSpawnCapacity():number{return availableRegions.size;}
/** Server/local-session-owned AI seats. A lobby client can request only a count. */
export function makeAISetups(count:number,seed=0):PlayerSetup[]{
 if(!Number.isSafeInteger(count)||count<0||count>=getSpawnCapacity())throw new Error('invalidAI');
 return Array.from({length:count},(_,i)=>({name:`AI ${i+1}`,leader:LEADERS[i%LEADERS.length],loadout:[KINDS[((seed>>>0)+i+1)%KINDS.length]],ai:true}));
}
function hash(seed:number,id:number):number{let x=(seed^Math.imul(id+1,0x9e3779b9))>>>0;x=Math.imul(x^(x>>>16),0x85ebca6b);x=Math.imul(x^(x>>>13),0xc2b2ae35);return(x^(x>>>16))>>>0;}
/** Seeded first pick, then maximize distance to the nearest already assigned
 * site. Include horizontal map wrap so opposite edges aren't treated as far
 * apart. Recompute only the requested prefix for ordinary small matches. */
export function chooseSpawnRegions(seed:number,count:number):number[]{
 if(!Number.isInteger(seed)||seed<0||seed>0xffffffff||!Number.isSafeInteger(count)||count<2||count>getSpawnCapacity())throw new Error('invalidSetup');
 const remaining=sites.regions.map(id=>({id,rank:hash(seed,id),distance:Infinity})),order:number[]=[];
 const width=BOUNDS.right-BOUNDS.left;
 while(order.length<count){
  let best=0;
  for(let i=1;i<remaining.length;i++){
   const a=remaining[i],b=remaining[best];
   if(a.distance>b.distance||(a.distance===b.distance&&a.rank<b.rank))best=i;
  }
  const [selected]=remaining.splice(best,1);order.push(selected.id);
  const origin=MAP[selected.id].center;
  for(const candidate of remaining){
   const target=MAP[candidate.id].center,x=Math.abs(origin.x-target.x);
   candidate.distance=Math.min(candidate.distance,Math.min(x,width-x)**2+(origin.z-target.z)**2);
  }
 }
 return order;
}
